public static int maxRegions(int N) {
    // Base case: 0 triangles divide the plane into 1 region
    if (N == 0) {
        return 1;
    }
    // Each new triangle can intersect all existing regions and add as many new regions as the number of its edges
    return 2 + N * (N + 1) / 2;
}

