public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a boolean array to represent visited intersections
    boolean[] visited = new boolean[n * n];

    // Create an adjacency list to represent the graph
    List<Integer>[] graph = new List[n * n];
    for (int i = 0; i < n * n; i++) {
        graph[i] = new ArrayList<>();
    }

    // Add edges to the graph based on the given paths
    for (int[] path : paths) {
        int u = path[0];
        int v = path[1];
        graph[u].add(v);
        graph[v].add(u);
    }

    // Helper function to perform DFS
    boolean dfs(int current, int target) {
        if (current == target) {
            return true;
        }
        visited[current] = true;

        for (int neighbor : graph[current]) {
            if (!visited[neighbor]) {
                if (dfs(neighbor, target)) {
                    return true;
                }
            }
        }

        return false;
    }

    // Perform DFS from the starting intersection to the ending intersection
    if (dfs(start[0] * n + start[1], end[0] * n + end[1])) {
        return "can be travelled";
    }

    // If DFS fails, return "cannot be travelled"
    return "cannot be travelled";
}

