public static double trimMean(int[] arr) {
        // Sort the array to easily remove the smallest and largest 5%
        Arrays.sort(arr);

        int n = arr.length;
        // Calculate the number of elements to remove from both ends
        int elementsToRemove = n / 20;

        // Calculate the sum of the remaining elements
        int sum = 0;
        for (int i = elementsToRemove; i < n - elementsToRemove; i++) {
            sum += arr[i];
        }

        // Calculate the mean of the remaining elements
        return (double) sum / (n - 2 * elementsToRemove);
    }

