public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int n = nums.length;
    boolean[][] possible = new boolean[n/2 + 1][sum + 1];
    possible[0][0] = true;
    for (int num : nums) {
        for (int i = Math.min(n / 2, n - 1); i >= 0; i--) {
            for (int j = Math.min(sum, sum - num); j >= 0; j--) {
                possible[i + 1][j + num] = possible[i + 1][j + num] || possible[i][j];
            }
        }
    }
    for (int i = 1; i <= n / 2; i++) {
        for (int j = 1; j <= sum; j++) {
            if (possible[i][j] && possible[n - i][(sum - j) * i / (n - i)] && (sum - j) * i != (n - i) * j) {
                return true;
            }
        }
    }
    return false;
}

