public int minInsertions(String s) {
    int balance = 0;
    int insertions = 0;
    int i = 0;

    while (i < s.length()) {
        if (s.charAt(i) == '(') {
            balance++;
            i++;
        } else if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
            i += 2;
        } else {
            insertions++;
            i++;
        }

        if (balance < 0) {
            insertions++;
            balance++;
        }
    }

    return insertions + balance * 2;
}

