public int findMinFibonacciNumbers(int k) {
    List<Integer> fibs = new ArrayList<>();
    fibs.add(1);
    fibs.add(1);

    // Generate Fibonacci numbers up to k
    while (fibs.get(fibs.size() - 1) < k) {
        fibs.add(fibs.get(fibs.size() - 1) + fibs.get(fibs.size() - 2));
    }

    // If the largest Fibonacci number is exactly k, return 1
    if (fibs.get(fibs.size() - 1) == k) {
        return 1;
    }

    // Use the largest Fibonacci number less than or equal to k and recursively find the minimum number of Fibonacci numbers for the remaining value
    int largestFib = fibs.get(fibs.size() - 1);
    fibs.remove(fibs.size() - 1);
    return 1 + findMinFibonacciNumbers(k - largestFib);
}

