public static boolean isBoomerang(int[][] points) {
    // Check if the given points form a boomerang
    // A boomerang is a triangle with a non-zero area
    // The area of the triangle formed by three points (x1, y1), (x2, y2), (x3, y3) is 0.5 * |x1(y2 - y3) + x2(y3 - y1) + x3(y1 - y2)|
    // If the area is zero, the points are collinear and do not form a boomerang

    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    int area = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);

    return area != 0;
}

