public static int calculateUniqueSum(int[] nums) {
    Map<Integer, Integer> numMap = new HashMap<>();
    for (int num : nums) {
        numMap.put(num, numMap.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (Map.Entry<Integer, Integer> entry : numMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

