public static int minPerfectSquareSum(int n) {
    if (n <= 3) {
        return n;
    }
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
        for (int x = 1; x * x <= i; x++) {
            dp[i] = Math.min(dp[i], dp[i - x * x] + 1);
        }
    }
    return dp[n];
}

