public static int minPerfectSquareSum(int n) {
    // Edge case: the minimum number of perfect squares that sum up to 0 is 0
    if (n == 0) {
        return 0;
    }

    // Create an array to store the minimum number of perfect squares for each value up to n
    int[] dp = new int[n + 1];

    // Base case: the minimum number of perfect squares that sum up to any number k (k > 0) is k
    // because we can always use 1^2 + 1^2 + ... + 1^2
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
    }

    // Iterate over each number from 2 to n
    for (int i = 2; i <= n; i++) {
        // For each number, try all smaller numbers to find the minimum number of perfect squares that sum up to i
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    // Return the minimum number of perfect squares that sum up to n
    return dp[n];
}

