public static int minPerfectSquareSum(int n) {
    // Base case
    if (n <= 3) {
        return n;
    }

    // This array will store the minimum number of squares needed for all numbers up to n
    int[] dp = new int[n + 1];

    // Base case initialization
    for (int i = 0; i <= n; i++) {
        dp[i] = i; // The maximum number of squares is i (1^2 + 1^2 + ...)
    }

    // Precompute the squares
    int[] squares = new int[(int) Math.sqrt(n) + 1];
    for (int i = 1; i <= (int) Math.sqrt(n); i++) {
        squares[i] = i * i;
    }

    // Fill dp array
    for (int i = 1; i <= n; i++) {
        for (int square : squares) {
            if (i >= square) {
                dp[i] = Math.min(dp[i], dp[i - square] + 1);
            } else {
                break;
            }
        }
    }

    return dp[n];
}

